-- Wine Discovery: your 10 real bottles replace the 10 made-up placeholders ("Sample Red 1"...).
-- Photos are static files in the app (public/bottles/<id>.jpg), referenced by label_image_path.
-- Taste details and prices were filled in from the label photos as a first draft: review and correct them in
-- src/data/bottles.json, then re-run `npm run bottles:sql` (it is an upsert, safe to run again).
-- Deleting the placeholders also removes any shelf items and ratings that point at them (cascade).
delete from public.wd_bottles where is_placeholder;

-- Generated by `npm run bottles:sql` from src/data/bottles.json. Do not edit by hand.
insert into public.wd_bottles (id, name, producer, vintage, type, price, body, sweetness, acidity, tannin, fruit_character, fruit_notes, flower_notes, extras, pairings, occasions, serve_tip, talking_point, easy_to_like, usually_sold_at, label_image_path, is_placeholder) values
  ('moet-imperial-brut', 'Impérial Brut', 'Moët & Chandon', null, 'sparkling', 55, 'medium', 'dry', 'zippy', 'low', 'fresh', array['apple-pear', 'citrus']::text[], array['white-flowers']::text[], array['toast']::text[], array['Salty snacks', 'Fried chicken', 'Oysters']::text[], array['gift', 'date-night', 'dinner-party']::text[], 'Serve it well chilled, about 46 to 50°F, as the back label says. Open it gently: hold the cork and twist the bottle.', 'Moët has been making Champagne in Épernay, France, since 1743. “Brut” on the label just means dry, not sweet.', true, array['Wine shops', 'Grocery stores']::text[], '/bottles/moet-imperial-brut.jpg', false),
  ('decoy-brut-cuvee', 'Brut Cuvée', 'Decoy', null, 'sparkling', 25, 'light', 'dry', 'zippy', 'low', 'fresh', array['apple-pear', 'citrus']::text[], array['white-flowers']::text[], array['toast']::text[], array['Salty snacks', 'Fried chicken', 'Cheese and crackers']::text[], array['date-night', 'gift', 'weeknight']::text[], 'Chill it for a few hours and open it gently. Hold the cork and twist the bottle.', 'It’s made the same way as Champagne (the label says “méthode champenoise”), but it comes from California.', true, array['Wine shops', 'Grocery stores']::text[], '/bottles/decoy-brut-cuvee.jpg', false),
  ('canvasback-cabernet', 'Red Mountain Cabernet Sauvignon', 'Canvasback', 2022, 'red', 35, 'full', 'dry', 'medium', 'high', 'jammy', array['dark-fruit', 'blue-fruit']::text[], array['purple-flowers']::text[], array['vanilla', 'baking-spice']::text[], array['Steak', 'BBQ ribs', 'Aged cheddar']::text[], array['dinner-party', 'gift']::text[], 'Pour it a little before dinner so it can open up, and serve it with something rich.', 'Red Mountain is a tiny spot in eastern Washington State known for big, bold Cabernet. The duck on the label is the canvasback duck the wine is named for.', false, array['Wine shops', 'Grocery stores']::text[], '/bottles/canvasback-cabernet.jpg', false),
  ('goldeneye-pinot-noir', 'Anderson Valley Pinot Noir', 'Goldeneye', 2022, 'red', 55, 'medium', 'dry', 'medium', 'low', 'fresh', array['red-berry', 'dark-fruit']::text[], array['roses']::text[], array['baking-spice', 'earthy']::text[], array['Roast chicken', 'Salmon', 'Mushroom pasta']::text[], array['dinner-party', 'date-night', 'gift']::text[], 'Serve it just a little cool: about 20 minutes in the fridge before you pour.', 'The label says it’s made in a solar-powered winery in California’s Anderson Valley, by the family behind Duckhorn.', true, array['Wine shops']::text[], '/bottles/goldeneye-pinot-noir.jpg', false),
  ('story-syrah', 'Bailey Vineyard Syrah', 'Story Winery', 2020, 'red', 35, 'full', 'dry', 'medium', 'high', 'jammy', array['dark-fruit', 'blue-fruit']::text[], array['purple-flowers']::text[], array['earthy', 'smoke']::text[], array['BBQ ribs', 'Grilled sausages', 'Hard cheese']::text[], array['dinner-party']::text[], 'Pour it a little before dinner so it can open up, and serve it with something rich.', 'Part of it is made in a qvevri (say “KWEV-ree”): a big clay pot buried in the ground, the way wine has been made in Georgia, the country, for about 8,000 years.', false, array['Wine shops', 'Specialty stores']::text[], '/bottles/story-syrah.jpg', false),
  ('clos-du-val-cabernet-franc', 'Estate Grown Cabernet Franc', 'Clos du Val', 2022, 'red', 75, 'medium', 'dry', 'medium', 'medium', 'fresh', array['red-berry', 'green']::text[], array['purple-flowers']::text[], array['earthy', 'baking-spice']::text[], array['Roast lamb', 'Pasta with tomato sauce', 'Hard cheese']::text[], array['dinner-party', 'gift']::text[], 'Open it 20 minutes before you pour, and serve it just under room temperature.', 'The wine is named for the swallows that nest at the estate each spring (“hirondelles” in French). The front of the label is just a quiet drawing.', false, array['Wine shops', 'Specialty stores']::text[], '/bottles/clos-du-val-cabernet-franc.jpg', false),
  ('beachaven-founders-rose', 'Founders Rosé', 'Beachaven Vineyards & Winery', null, 'rosé', 16, 'light', 'off-dry', 'medium', 'low', 'fresh', array['red-berry']::text[], array['roses']::text[], '{}'::text[], array['Cheese and crackers', 'Spicy takeout', 'Salad']::text[], array['weeknight', 'date-night', 'gift']::text[], 'Serve it cold, straight from the fridge.', 'Every grape in it was grown in Tennessee, and the label shows the two founders the wine honors.', true, array['The winery']::text[], '/bottles/beachaven-founders-rose.jpg', false),
  ('migration-chardonnay', 'Keefer Ranch Chardonnay', 'Migration', 2023, 'white', 45, 'full', 'dry', 'zippy', 'low', 'fresh', array['stone-fruit', 'apple-pear', 'citrus']::text[], '{}'::text[], array['toast', 'vanilla']::text[], array['Roast chicken', 'Creamy pasta', 'Lobster']::text[], array['dinner-party', 'date-night', 'gift']::text[], 'Chill it, then leave it out for about 10 minutes before you pour so the flavors come through.', 'The back label mentions peach, Fuji apple and citrus, so you can taste along and see if you find them.', true, array['Wine shops', 'Specialty stores']::text[], '/bottles/migration-chardonnay.jpg', false),
  ('duckhorn-sauvignon-blanc', 'North Coast Sauvignon Blanc', 'Duckhorn Vineyards', 2025, 'white', 25, 'medium', 'dry', 'zippy', 'low', 'fresh', array['citrus', 'green', 'tropical']::text[], array['white-flowers']::text[], '{}'::text[], array['Salad', 'Seafood', 'Goat cheese']::text[], array['weeknight', 'date-night', 'dinner-party']::text[], 'Serve it well chilled, about 2 hours in the fridge.', 'This is a bottle made for Duckhorn’s 50th anniversary, and it says so on the label.', true, array['Wine shops', 'Grocery stores']::text[], '/bottles/duckhorn-sauvignon-blanc.jpg', false),
  ('dr-loosen-blue-slate-riesling', 'Blue Slate Riesling Kabinett', 'Dr. Loosen', 2025, 'white', 20, 'light', 'off-dry', 'zippy', 'low', 'fresh', array['citrus', 'apple-pear', 'stone-fruit']::text[], array['white-flowers']::text[], '{}'::text[], array['Spicy takeout', 'Thai food', 'Sushi']::text[], array['weeknight', 'date-night']::text[], 'Chill it well. The cold keeps the sweetness in balance with the zip.', 'It’s only 8% alcohol, much lighter than most wines, and it comes from steep blue slate hillsides in Germany’s Mosel valley.', true, array['Wine shops', 'Grocery stores']::text[], '/bottles/dr-loosen-blue-slate-riesling.jpg', false)
on conflict (id) do update set
  name = excluded.name,
  producer = excluded.producer,
  vintage = excluded.vintage,
  type = excluded.type,
  price = excluded.price,
  body = excluded.body,
  sweetness = excluded.sweetness,
  acidity = excluded.acidity,
  tannin = excluded.tannin,
  fruit_character = excluded.fruit_character,
  fruit_notes = excluded.fruit_notes,
  flower_notes = excluded.flower_notes,
  extras = excluded.extras,
  pairings = excluded.pairings,
  occasions = excluded.occasions,
  serve_tip = excluded.serve_tip,
  talking_point = excluded.talking_point,
  easy_to_like = excluded.easy_to_like,
  usually_sold_at = excluded.usually_sold_at,
  label_image_path = excluded.label_image_path,
  is_placeholder = excluded.is_placeholder;

